import 'package:analyzer/dart/analysis/results.dart';
import 'package:analyzer/dart/ast/ast.dart';
import 'package:analyzer/dart/ast/visitor.dart';
import 'package:codeguardian_core/codeguardian_core.dart';

import 'rule_utils.dart';

/// Matches variable/field/constant names that look like they hold a secret
/// (API key, password, token, ...).
///
/// Exposed at top level (rather than kept private to [HardcodedSecretRule])
/// so other packages that need to detect the exact same "looks like a
/// secret name" shape -- e.g. `codeguardian_ai`'s pre-send redaction of code
/// before it reaches an AI provider -- share a single source of truth
/// instead of maintaining a second copy of this pattern that could drift.
final RegExp secretNamePattern = RegExp(
  r'(secret|password|passwd|api[_]?key|access[_]?key|private[_]?key|'
  r'auth[_]?token|access[_]?token)',
  caseSensitive: false,
);

/// Matches dotted, all-lowercase keys such as `auth.set_password_title`, the
/// shape produced by i18n key generators.
final RegExp _dottedKeyPattern = RegExp(r'^[a-z0-9_]+(\.[a-z0-9_]+)+$');

/// Whether [value] itself looks like a secret rather than a path, an i18n
/// key, or a plain label. See [secretNamePattern] for why this is a
/// top-level function rather than a private method.
bool looksLikeSecretValue(String value) {
  if (value.contains('/')) return false;
  if (_dottedKeyPattern.hasMatch(value)) return false;
  if (!value.contains(RegExp('[0-9]'))) return false;
  return true;
}

/// Flags variables, fields, and constants whose name looks like it holds a
/// secret (API key, password, token, ...) and whose value is a non-empty
/// string literal that itself looks like a secret, hardcoded directly in
/// source.
///
/// A secret-shaped name alone isn't enough: route paths (`resetPassword =
/// '/v1/auth/reset-password'`), asset paths, i18n key constants (`.g.dart`
/// files generated by `easy_localization`, whose keys are dotted strings
/// like `auth.set_password_title`), and header-name labels (`apiKeyHeader =
/// 'Api-Key'`) all have secret-shaped names but non-secret values. Generated
/// files are skipped outright since a finding there isn't actionable.
class HardcodedSecretRule implements CodeGuardianRule {
  /// Creates the rule.
  const HardcodedSecretRule();

  @override
  String get id => 'hardcoded-secret';

  @override
  List<Finding> check(ResolvedUnitResult unit) {
    if (isGeneratedFile(unit)) return const [];

    final visitor = _Visitor(unit);
    unit.unit.accept(visitor);
    return visitor.findings;
  }
}

class _Visitor extends RecursiveAstVisitor<void> {
  _Visitor(this.unit);

  final ResolvedUnitResult unit;
  final List<Finding> findings = [];

  @override
  void visitVariableDeclaration(VariableDeclaration node) {
    super.visitVariableDeclaration(node);

    final initializer = node.initializer;
    final name = node.name.lexeme;
    if (initializer is! SimpleStringLiteral) return;
    final value = initializer.value.trim();
    if (value.isEmpty) return;
    if (!secretNamePattern.hasMatch(name)) return;
    if (!looksLikeSecretValue(value)) return;

    final location = unit.lineInfo.getLocation(node.name.offset);
    findings.add(Finding(
      ruleId: 'hardcoded-secret',
      category: Category.security,
      severity: Severity.high,
      file: unit.path,
      line: location.lineNumber,
      column: location.columnNumber,
      message: "'$name' looks like a hardcoded secret; move it out of "
          'source (e.g. environment variables or secure storage) instead of '
          'committing it as a string literal.',
      snippet: lineSnippet(unit, location.lineNumber),
      cweId: 'CWE-798',
      masvsId: 'MASVS-STORAGE-1',
    ));
  }
}
